INSERT INTO media (id, publication_id, kind, storage_key, filename, mime_type, byte_size) VALUES ('c00629459f3078c8592681762a763939', '4cd630440b929be61d9c36769b788da2', 'image', 'pub/4cd630440b929be61d9c36769b788da2/c00629459f3078c8592681762a763939/medijske-manipulacije-protiv-volje.jpg', 'medijske-manipulacije-protiv-volje.jpg', 'image/jpeg', 22369);
INSERT INTO posts (id, publication_id, slug, title, subtitle, body_md, body_html, cover_media_id, category_id, kind, status, published_at) VALUES ('e9585736ac44b21fb863d883e44800fc', '4cd630440b929be61d9c36769b788da2', 'medijske-manipulacije-protiv-volje-gradana', 'DEMO ### 003 Medijske manipulacije protiv volje građana', '', 'Mostova inicijativa, kolokvijalno zvana „Dosta je stožerokracije“, skupila je 400 000 potpisa čime debelo prelazi potreban prag za raspisivanje referenduma. Građani RH tim su brojem jasno pokazali da nemaju povjerenja u stožer -  objektivnije promatrače to ne bi trebalo začuditi budući da su prosvjedi protiv stožera i njegovih mjera brojali i preko 50 000 ljudi. Indikativna je, međutim, reakcija mainstream medija na Mostovu objavu uspjeha u kojoj četiri medija - jedan za drugim - na potpuno isti način prenose tu vijest; naime, usprkos tome što se na Mostovoj konferenciji većina vodećih ljudi iz stranke izmijenila na mikrofonu te se većinski fokusirala na zahvaljivanje volonterima i glasačima, mediji konferenciju prenose pod naslovom „Miletić: Tresem se od radosti!“ citirajući jednu rečenicu iz petominutnog govora Marina Miletića. Znajući modus operandi većine medija posljednje dvije godine (a i duže) u kojem je svaka riječ plasirana u pravo vrijeme na pravo mjesto, postavlja se pitanje *cui bono* – s kojim ciljem je stavljen takav naslov?

Nakon ranije navedenog prosvjeda na zagrebačkom glavnom trgu, glavne vijesti mainstream medija bile su o par nekakvih minornih incidenata koji su se navodno dogodili; jedan od njih uključuje šamar jednom novinaru za koji do danas nije dan nijedan dokaz što je jako čudno budući da je trg bio krcat novinarskim kamerama, policijskim kamerama i mobitelima. Slično tomu, prije koji tjedan „medij za provjeru činjenica“ Faktograf objavio je kako su hakirani te da primaju prijetnje – do danas ne znamo što se od toga uistinu dogodilo budući da nije dan nijedan dokaz. Faktograf je s tom vijesti izašao u javnost dan nakon što je ušao u žestok sukob s poduzetnikom Nenadom Bakićem koji je tvrdio da mu Faktograf, koji ima ugovor s Facebookom u kojem mu Facebook daje pravo da određuje koje su informacije na njegovoj platformi lažne, bez razloga briše postove i smanjuje *reach*. Iz komentara tog sukoba, kao i iz reakcija (lajkovi i slično), bilo je očito da je većina stala na Bakićevu stranu te bila izrazito kritična prema Faktografu koji, čini se, glumi nekakvog arbitra istine kao u najgorim distopijskim romanima. Nakon takvog „poraza“ u javnoj diskusiji, Faktograf izlazi s ranije opisanom vijesti prijetnji i hakerskih napada. Kao što je već navedeno, mi ne možemo znati koliko je tih optužbi istinito budući da ni za jednu nismo vidjeli nijedan dokaz, međutim, možemo iščitati trend iz medijskog ponašanja u takvim situacijama gdje se ciljano skreće fokus s merituma na ono što im u tom trenutku odgovara, što je često stavljanje sebe u poziciju žrtve čime se implicitno moralno ucjenjuju svi koji nastavljaju s kritikama. U današnjoj situaciji, mediji su skretanje fokusa s činjenice da je 400 000 ljudi jasno izrazilo svoje neslaganje sa stožerom pokušali ostvariti stavljanjem u centar pozornosti osobu s kojom se dosta ljudi ideološki ne slaže hvatajući se pritom za jednu izjavu koja van konteksta može zvučati čudno.

Cui bono? Mainstream mediji ne samo da takvim ponašanjem ponovno banaliziraju cjelokupan problem nošenja s pandemijom (katalizirajući degradiranje diskursa na birtijsku razinu „moji protiv tvojih“), već i pljuju u lice 400 000 ljudi svodeći ih pod isti nazivnik jedne osobe. Kao što je to sad već ustaljena praksa, ako se skupi ogroman broj ljudi koji se s nama ideološki ne slažu, uvijek možemo izdvojiti nekog problematičnog među njima (kojeg će uvijek biti budući da je određen postotak svake grupe problematičan) te sve ostale staviti u isti taj koš – sjetimo se samo vijesti kako se u Beču skupljaju prosvjednici protiv covid mjera od kojih su „neki ekstremni desničari“ – tko, koliki postotak, ima li to veze sa samim prosvjedom, gdje su vam dokazi i slična „suvišna pitanja“ nisu adresirana. Činjenica da je Marin Miletić u stvarnosti problematičan isključivo toliko koliko njegovi pogledi na svijet nekome ne odgovaraju (pa mu je lakše gledati ga kao luđaka nego civilizirano raspravljati s njim) je zasebna tema. Korist je, dakle, takvog manipuliranja javne diskusije u odvlačenju iste na stranu koja medijima odgovara koja je, vjerojatno ne slučajno, često simplificirana i banalna do bola. Tužno je, s tim na umu, gledati na kakve grane je spalo novinarstvo kojem je nekad jedna od glavnih uloga bila podizanje javnog diskursa na smislenu, argumentiranu i duboku razinu.

Ne, gospodo novinari, ovaj referendum nije imao veze s Mostom kao političkom strankom, već s činjenicom da nam sudbinu posljednje dvije godine kroje ljudi koje nitko nije izabrao, koji su upitne stručnosti te koji kontinuirano donose kontradiktorne mjere kao što je zabrana ulaska u javne servise (koji funkcioniraju na novcu građana) dok se istovremeno u kockarnice ili birtije može ući bez ikakvog problema. 

