INSERT INTO media (id, publication_id, kind, storage_key, filename, mime_type, byte_size) VALUES ('a535bf71e5e888776e14a0aeeafad5bf', '4cd630440b929be61d9c36769b788da2', 'image', 'pub/4cd630440b929be61d9c36769b788da2/a535bf71e5e888776e14a0aeeafad5bf/u-posljednjih-par-godina-hdz-je.png', 'u-posljednjih-par-godina-hdz-je.png', 'image/png', 53974);
INSERT INTO posts (id, publication_id, slug, title, subtitle, body_md, body_html, cover_media_id, category_id, kind, status, published_at) VALUES ('cccc838f793d180e0db893e4e662d8fc', '4cd630440b929be61d9c36769b788da2', 'u-posljednjih-par-godina-hdz-je', 'DEMO ### 062 U posljednjih par godina HDZ je:', '', 'U posljednjih par godina HDZ je:

\- oštetila RH za višemilijunski iznos u aferi Vjetroelektrane,

\- oštetila RH za višemilijunski iznos u aferi JANAF,

\- oštetila RH za 2,6 milijuna u aferi bivšeg ministra graditeljstva, dok istovremeno u 2 godine nije započela smislenu rekonstrukciju privatnih i javnih objekata stradalih u razornim potresima (podsjećamo, naši sugrađani iz Petrinje i dalje spavaju u kontejnerima, dok se organizirani kriminalci s vlasti bogate),

\- oštetila RH i EU za 13 milijuna kuna u aferi Softver,

\- radi zdravstvene krize osnovala je stožer kojim indikativno upravlja ministar MUP-a (ne zdravstva),a većina članova stožera (uz iznimku 2 doktora) nema nikakve veze sa zdravstvom - toliko o njihovoj tezi "slušaj struku",

\- usred zdravstvene krize dala milijunski iznos cvjećarskoj firmi, firmi koju vodi poznanik ministra zdravstva, za izradu polufunkcionalnog softvera, 

\- od početka pandemije nije poštovala zakon o javnoj nabavi prilikom nabavke medicinske opreme već je na svaku nabavku stavljala klasifikaciju "tajno",

\- neprestano i sustavno zastrašivala javnost pandemijom preko političkih aktera, "znanstvenika" (koji po definiciji znanosti to ustvari nisu) i podobnih medija,

\- nametala pseudoznanstvene i antidemokratske covid mjere koje su ljudima oduzimale temeljna prava na rad, slobodu kretanja, slobodu govora i okupljanja, itd., a sve to bez otvorene javne rasprave, bez znanstvene podloge i bez mogućnosti opovrgavanja nametnutih mjera,

\- uvela segregacijske i neefikasne covid potvrde kojima preko 40% građana nije moglo koristiti javne institucije koje funkcioniraju na novcu istih tih građana,

\- agresivno i ucjenjivački nametala covid cjepivo, iako službena metodologija za praćenje efikasnosti cjepiva ne postoji,

\- onemogućila (preko Ustavnog suda čiji predsjednik je kum s dva visokopozicionirana HDZ-ovca) referendum koji je potpisalo preko 400 000 ljudi,

\- oštetila RH za milijardu kuna preko afere u INI usred globalne energetske krize, dok je istovremeno forsirala građane na "stezanje remena".

Podsjećamo, sve ovo samo u zadnjih par godina. U tom je periodu smijenjeno i 20 ministara. 

Pitanje, stoga, nije hoćete li doći na prosvjed, već hoćete li svojom neaktivnošću dopustiti da stranka pravomoćno osuđena za korupciju nastavlja korupcijom gušiti i uništavati našu državu (radeći to uz potporu svoje glasačke mašinerije, koja je na zadnjim izborima, zbog ciljano nepromijenjenog disfunkcionalnog izbornog sustava, činila manje od 17% od ukupnog broja birača).

![](https://substackcdn.com/image/fetch/$s_!IwCb!,f_auto,q_auto:good,fl_progressive:steep/https%3A%2F%2Fsubstack-post-media.s3.amazonaws.com%2Fpublic%2Fimages%2F6e74d865-fa41-4d3a-a9bb-8b60ebfaa1e6_400x400.png)', '<p>U posljednjih par godina HDZ je:</p>
<p>- oštetila RH za višemilijunski iznos u aferi Vjetroelektrane,</p>
<p>- oštetila RH za višemilijunski iznos u aferi JANAF,</p>
<p>- oštetila RH za 2,6 milijuna u aferi bivšeg ministra graditeljstva, dok istovremeno u 2 godine nije započela smislenu rekonstrukciju privatnih i javnih objekata stradalih u razornim potresima (podsjećamo, naši sugrađani iz Petrinje i dalje spavaju u kontejnerima, dok se organizirani kriminalci s vlasti bogate),</p>
