INSERT INTO media (id, publication_id, kind, storage_key, filename, mime_type, byte_size) VALUES ('55fd81f0f3b7f44488fbe77aec976c60', '4cd630440b929be61d9c36769b788da2', 'image', 'pub/4cd630440b929be61d9c36769b788da2/55fd81f0f3b7f44488fbe77aec976c60/slom-covid-ideologije-tko-je-odgovoran.jpg', 'slom-covid-ideologije-tko-je-odgovoran.jpg', 'image/jpeg', 27199);
INSERT INTO posts (id, publication_id, slug, title, subtitle, body_md, body_html, cover_media_id, category_id, kind, status, published_at) VALUES ('ef19e233c95b48a3707fb3d659712ea6', '4cd630440b929be61d9c36769b788da2', 'slom-covid-ideologije-tko-je-odgovoran', 'DEMO ### 097 Slom covid ideologije: tko je odgovoran?', '', '![](https://substackcdn.com/image/fetch/$s_!Y-x5!,f_auto,q_auto:good,fl_progressive:steep/https%3A%2F%2Fsubstack-post-media.s3.amazonaws.com%2Fpublic%2Fimages%2F2bcec44c-8062-4ecc-87e5-6475361547f2_400x300.jpeg)

Odlično, neka nam sada gospoda iz HZJZ - Hrvatski zavod za javno zdravstvo kažu tko će snositi odgovornost za posljedice ovih pseudoznanstvenih srednjovjekovnih antidemokratskih mjera, kao što su ekonomska kriza (stotine milijuna ljudi diljem svijeta bačenih u apsolutno siromaštvo kao posljedica iracionalno zamrznute ekonomije), demolirani i izgubljeni poslovi, mentalna oboljenja (anksioznost, depresija i netretiranje onih još intruzivnijih), neizbježni porast suicida, otežano i izgubljeno školovanje djece (milijuni djece afričkih država nikada se nisu vratili u školu nakon istih takvih mjera), upeterostručeni brojevi govornih poteškoća kod djece, porast obiteljskog nasilja kao posljedica zatvaranja žrtava u dom s nasilnicima, porast oboljenja i smrti od ostalih netretiranih i nepregledavanih bolesti (neke od kojih imaju 100x veću smrtnost od covida), nepovratno uništeni demokratski temelji kao što je sloboda prosvjednih okupljanja protiv takvih "mjera" vlasti, i tako dalje.

Jesu li vam sudbine svijeta i svih tih ljudi uistinu samo broj na papiru koji ste spremni uništiti radi vaše svojevoljne banalno zle sljepoće?

Dotični je gospodin, koji je kao glavni epidemiolog u HZJZ-u definicija te toliko zazivane "struke", s ovom evaluacijom zakasnio dobre 3 godine (https://sapereaudecro.blogspot.com/.../propast-filozofije...), no kako bi rekli Amerikanci, better late than never. Nadajmo se da će ostali ideolozi slijediti ovo kasno buđenje savjesti, te da će netko za ovu skandaloznu globalno-fašistoidnu trogodišnju tragediju odgovarati. 🤡', '<p><img src="https://substackcdn.com/image/fetch/$s_!Y-x5!,f_auto,q_auto:good,fl_progressive:steep/https%3A%2F%2Fsubstack-post-media.s3.amazonaws.com%2Fpublic%2Fimages%2F2bcec44c-8062-4ecc-87e5-6475361547f2_400x300.jpeg" alt=""></p>
<p>Odlično, neka nam sada gospoda iz HZJZ - Hrvatski zavod za javno zdravstvo kažu tko će snositi odgovornost za posljedice ovih pseudoznanstvenih srednjovjekovnih antidemokratskih mjera, kao što su ekonomska kriza (stotine milijuna ljudi diljem svijeta bačenih u apsolutno siromaštvo kao posljedica iracionalno zamrznute ekonomije), demolirani i izgubljeni poslovi, mentalna oboljenja (anksioznost, depresija i netretiranje onih još intruzivnijih), neizbježni porast suicida, otežano i izgubljeno školovanje djece (milijuni djece afričkih država nikada se nisu vratili u školu nakon istih takvih mjera), upeterostručeni brojevi govornih poteškoća kod djece, porast obiteljskog nasilja kao posljedica zatvaranja žrtava u dom s nasilnicima, porast oboljenja i smrti od ostalih netretiranih i nepregledavanih bolesti (neke od kojih imaju 100x veću smrtnost od covida), nepovratno uništeni demokratski temelji kao što je sloboda prosvjednih okupljanja protiv takvih &quot;mjera&quot; vlasti, i tako dalje.</p>
<p>Jesu li vam sudbine svijeta i svih tih ljudi uistinu samo broj na papiru koji ste spremni uništiti radi vaše svojevoljne banalno zle sljepoće?</p>
<p>Dotični je gospodin, koji je kao glavni epidemiolog u HZJZ-u definicija te toliko zazivane &quot;struke&quot;, s ovom evaluacijom zakasnio dobre 3 godine (<a href="https://sapereaudecro.blogspot.com/.../propast-filozofije">https://sapereaudecro.blogspot.com/.../propast-filozofije</a>...), no kako bi rekli Amerikanci, better late than never. Nadajmo se da će ostali ideolozi slijediti ovo kasno buđenje savjesti, te da će netko za ovu skandaloznu globalno-fašistoidnu trogodišnju tragediju odgovarati. 🤡</p>
