INSERT INTO media (id, publication_id, kind, storage_key, filename, mime_type, byte_size) VALUES ('27d4dcde64a7126afb6eba0912162aca', '4cd630440b929be61d9c36769b788da2', 'image', 'pub/4cd630440b929be61d9c36769b788da2/27d4dcde64a7126afb6eba0912162aca/zene-kao-sredstvo-pravovjerne-borbe.jpg', 'zene-kao-sredstvo-pravovjerne-borbe.jpg', 'image/jpeg', 58427);
INSERT INTO posts (id, publication_id, slug, title, subtitle, body_md, body_html, cover_media_id, category_id, kind, status, published_at) VALUES ('11ad99170b4e71901759775330ae9d04', '4cd630440b929be61d9c36769b788da2', 'zene-kao-sredstvo-pravovjerne-borbe-zorana-sprajca', 'DEMO ### 156 Žene kao sredstvo pravovjerne borbe Zorana Šprajca', '', '![](https://substackcdn.com/image/fetch/$s_!Zh_z!,f_auto,q_auto:good,fl_progressive:steep/https%3A%2F%2Fsubstack-post-media.s3.amazonaws.com%2Fpublic%2Fimages%2F157b973f-fda8-46f1-8cd5-f15050398ede_400x300.jpeg)

Kvazinovinar Zoran Šprajc na najpodmukliji način parazitira na tragičnom događaju kako bi ga iskoristio u svoje ideološke svrhe. Navodi tako da je slučaj silovanja žene od strane dvojice policajaca u Lici "vjerski čin", povezujući ga nejasnom, osnovnoškolskom logikom s ljudima koji se na hrvatskim trgovima javno mole.

Ovaj progresivni samoprozvani borac za ženska prava, dakle, koristi žrtvu žene kako bi se mogao obračunati s ideološkim neistomišljenicima, no takvo će nas njegovo djelovanje nešto manje čuditi kada se sjetimo kakvu ulogu je odigrao tijekom covid manije. Tada je, naime, od osobe koja svojim usiljenim humorom sprda neke od apsurdnih covid mjera preko noći postao njihov dečko s postera. Nismo sigurni plaća li i koliko HZJZ glumce u svojim propagandističkim big pharma reklamama, no gospodina bi se moglo priupitati, istine radi, koliko je njegova glumačka karijera u tim HZJZ-ovim tragikomičnim filmićima utjecala na njegovu prekonoćnu promjenu narativa.

Nadalje, nejasno je zašto takav vrli borac za ženska prava, kao i ostatak njegovih progresivnih kolega, poslušnički i kukavički šuti kada se žene u ime neefikasnih vudu pandemijskih mjera bespravno zatvara u domove, što uključuje i žrtve obiteljskog nasilja koje tako bivaju osuđene na cjelodnevni boravak s nasilnicima.

Oba ova slučaja gospodinovog pristranog antinovinarsko-aktivističkog djelovanja ukazuju na širi problem učestalosti objektivizacije žena od strane onih koji su si u ovom ludom duhu vremena samopripisali monopol na brigu za žene. Ima li danas boljeg načina kako opravdati a) nelegitimno antidemokratsko ugrabljivanje moći i b) intelektualno lijeno ideološko obračunavanje od toga da se ona umotaju u celofan "borbe za nečija prava"? Kao što je Chesterton najviše volio putovati zato da bi se pri povratku kući podsjetio koliko voli svoj dom, tako nam moderni pravovjernici valjda žele oduzeti prava kako bi nas potaknuli da ih se zaželimo te budemo zahvalni kada nam ih se udostoje vratiti. 

Na kraju, osim standardnog progresivnog licemjerja, u ovom kontekstu valja još jednom podsjetiti i na koliko niske grane se disciplina novinarstva spustila. Ovakva objava, u kojoj se skupina ljudi javno krivi za kriminalno djelo s kojim nemaju nikakve veze, sukreirajući tako atmosferu linča prema toj skupini, u svakoj bi normalnoj državi (u normalno vrijeme) bila tuživa - kako protiv pojedinačnog novinara koji iza nje stoji tako i za medijsku kompaniju na čijoj platformi je objavljena. Nepojmljivo je do prije samo 10-ak godina bilo da se jedan srednjostrujaški novinar na ovakav najprljaviji manihejski način odnosi prema bilo kojoj društvenoj temi, a danas je to od iznimke postalo pravilo. 

Ponovno smo, eto, u vremenu u kojem se pravovjernicima službenih narativa sve oprašta, pa tako i ti sveprisutni paradoksi u kojima se žene u ime žena koriste kao objekti ostvarenja nečijih ideoloških ciljeva - bilo u kontekstu parazitiranja na njihovoj žrtvi, bilo kada ih se, skupa s ostalim građanima, treba ucjenama natjerati na konzumaciju farmakoloških proizvoda. No dobro, tko je kriv nama nazadnima što već nismo naučili da žena u 21. stoljeću mora imati pravo izbora - naravno, samo ako je najnovijom dozom nametnutog cjepiva ažurirala svoju žensku samodostatnost.', '<p><img src="https://substackcdn.com/image/fetch/$s_!Zh_z!,f_auto,q_auto:good,fl_progressive:steep/https%3A%2F%2Fsubstack-post-media.s3.amazonaws.com%2Fpublic%2Fimages%2F157b973f-fda8-46f1-8cd5-f15050398ede_400x300.jpeg" alt=""></p>
<p>Kvazinovinar Zoran Šprajc na najpodmukliji način parazitira na tragičnom događaju kako bi ga iskoristio u svoje ideološke svrhe. Navodi tako da je slučaj silovanja žene od strane dvojice policajaca u Lici &quot;vjerski čin&quot;, povezujući ga nejasnom, osnovnoškolskom logikom s ljudima koji se na hrvatskim trgovima javno mole.</p>
