INSERT INTO media (id, publication_id, kind, storage_key, filename, mime_type, byte_size) VALUES ('8a9c8c07699863285490e450d89456d2', '4cd630440b929be61d9c36769b788da2', 'image', 'pub/4cd630440b929be61d9c36769b788da2/8a9c8c07699863285490e450d89456d2/mracna-strana-urusavanja-zagrebackog.jpg', 'mracna-strana-urusavanja-zagrebackog.jpg', 'image/jpeg', 153788);
INSERT INTO posts (id, publication_id, slug, title, subtitle, body_md, body_html, cover_media_id, category_id, kind, status, published_at) VALUES ('d9f86e8db27eba03a8a1aa04bb7f15b2', '4cd630440b929be61d9c36769b788da2', 'mracna-strana-urusavanja-zagrebackog-prometa-kratki-osvrt', 'DEMO ### 247 Mračna strana urušavanja zagrebačkog prometa - kratki osvrt', '', '![](https://substackcdn.com/image/fetch/$s_!IrZo!,f_auto,q_auto:good,fl_progressive:steep/https%3A%2F%2Fsubstack-post-media.s3.amazonaws.com%2Fpublic%2Fimages%2F640c8b1f-dfdd-4b0d-8772-1b0fb63fa8c1_640x546.jpeg)

Još jednom imamo priliku svjedočiti pogrešnim premisama na kojima se vodi neka javna rasprava, ovoga puta konkretno javna rasprava o prometnim promjenama u Zagrebu. Promašeno je o svemu što se događa raspravljati iz prizme svakodnevne politike, jer aktualna vlast nije sačinjena od svakodnevnih političara. Kada govorimo o zagrebačkom vodstvu, ne govorimo o dobronamjernoj ali neiskusnoj skupini ljudi, već o iznimno dobro ideološki potkovanim pojedincima. Možemo ići toliko daleko da kažemo da se radi o osobama koje su spremne u očima javnosti kontinuirano ispadati nesposobne pod cijenu toga da se ne otkrije koliko su zapravo sposobne - ali ne u upravljanju gradom, već u upravljanju građanima.

Slušamo tako analize novog sustava naplate parkiranja, pritom se nijednom ne pitajući što bi moglo zapravo stajati iza toga – ima li novi blokovski parking možda neke veze s konceptom kojeg je gradonačelnik nedavno podržao, konceptom tzv. 15-minutnih gradova, odnosno sa zatvaranjem građana u gradske blokove te naplatom svakog izlaska pod krinkom nekih od stvorenih i/ili stvarnih kriza (virus, klima i sl.)? Hoće li ogroman broj nedavno podignutih nadzornih kamera po gradu u nekom trenutku biti prenamijenjen u tu svrhu, s obzirom na to da je nadzor kretanja građana preduvjet takvog koncepta? Ne treba li ova pitanja ozbiljno razmotriti znajući za radikalnost progresivaca na vlasti u kontekstu zelene teorije?

Nadalje, ima li urušavanje zagrebačkog prometa naizgled stihijskim radovima i (ne)promišljenim uvođenjem biciklističkih staza na najgorim mjestima veze s činjenicom da je gradonačelnikov glavni čovjek za promet, Andro Pavuna, jasno i glasno izrazio svoju mržnju prema automobilima? Slijedom toga, kada putujemo preko sat vremena od jednog kraja grada do drugog, svjedočimo li tada samo standardnim prometnim gužvama ili pak planskoj demotivaciji korištenja automobila, koje bismo jednako teško i uz plaćanje harača mogli koristiti i u Tomaševićevom snu 15-minutnog grada? Inače, spomenuti je Pavuna diplomirao psihologiju, a kasnije se, osim u ljevičarskom aktivizmu, usavršavao u disciplini prometne psihologije, koja među ostalim odgovara na pitanje kako prometom možemo modelirati ljudski um. Hoće li ga itko od režimskih medija ikada upitati koristi li, s obzirom na prometni kaos kojemu svjedočimo, svoje znanje u svrhu društvenog inženjeringa?

Vjerojatno ne. Vjerojatno ćemo nastaviti razglabati o njihovim potezima kao da se radi o naivnim glupkastim, ponešto radikalnim, ali dobronamjernim dečkima. Ili ćemo pak, za što ima najviše šanse, jednostavno nastaviti pasivno pristajati na sve što nam se servira, pa kada se jedan dan probudimo i kada, umjesto samo za svoje parkirno mjesto, gradu budemo morali plaćati i za napuštanje svog dodijeljenog bloka, tada ćemo se možda upitati kako je do ovoga došlo. A možda i nećemo. Ako smo već zaboravili segregaciju ogradama od prije koju godinu od tih samoprozvanih boraca za društvenu pravdu, izgledno je da ćemo zaboraviti i buduća poigravanja našim slobodama, gradovima i umovima.

#SapereAude', '<p><img src="https://substackcdn.com/image/fetch/$s_!IrZo!,f_auto,q_auto:good,fl_progressive:steep/https%3A%2F%2Fsubstack-post-media.s3.amazonaws.com%2Fpublic%2Fimages%2F640c8b1f-dfdd-4b0d-8772-1b0fb63fa8c1_640x546.jpeg" alt=""></p>
<p>Još jednom imamo priliku svjedočiti pogrešnim premisama na kojima se vodi neka javna rasprava, ovoga puta konkretno javna rasprava o prometnim promjenama u Zagrebu. Promašeno je o svemu što se događa raspravljati iz prizme svakodnevne politike, jer aktualna vlast nije sačinjena od svakodnevnih političara. Kada govorimo o zagrebačkom vodstvu, ne govorimo o dobronamjernoj ali neiskusnoj skupini ljudi, već o iznimno dobro ideološki potkovanim pojedincima. Možemo ići toliko daleko da kažemo da se radi o osobama koje su spremne u očima javnosti kontinuirano ispadati nesposobne pod cijenu toga da se ne otkrije koliko su zapravo sposobne - ali ne u upravljanju gradom, već u upravljanju građanima.</p>
<p>Slušamo tako analize novog sustava naplate parkiranja, pritom se nijednom ne pitajući što bi moglo zapravo stajati iza toga – ima li novi blokovski parking možda neke veze s konceptom kojeg je gradonačelnik nedavno podržao, konceptom tzv. 15-minutnih gradova, odnosno sa zatvaranjem građana u gradske blokove te naplatom svakog izlaska pod krinkom nekih od stvorenih i/ili stvarnih kriza (virus, klima i sl.)? Hoće li ogroman broj nedavno podignutih nadzornih kamera po gradu u nekom trenutku biti prenamijenjen u tu svrhu, s obzirom na to da je nadzor kretanja građana preduvjet takvog koncepta? Ne treba li ova pitanja ozbiljno razmotriti znajući za radikalnost progresivaca na vlasti u kontekstu zelene teorije?</p>
<p>Nadalje, ima li urušavanje zagrebačkog prometa naizgled stihijskim radovima i (ne)promišljenim uvođenjem biciklističkih staza na najgorim mjestima veze s činjenicom da je gradonačelnikov glavni čovjek za promet, Andro Pavuna, jasno i glasno izrazio svoju mržnju prema automobilima? Slijedom toga, kada putujemo preko sat vremena od jednog kraja grada do drugog, svjedočimo li tada samo standardnim prometnim gužvama ili pak planskoj demotivaciji korištenja automobila, koje bismo jednako teško i uz plaćanje harača mogli koristiti i u Tomaševićevom snu 15-minutnog grada? Inače, spomenuti je Pavuna diplomirao psihologiju, a kasnije se, osim u ljevičarskom aktivizmu, usavršavao u disciplini prometne psihologije, koja među ostalim odgovara na pitanje kako prometom možemo modelirati ljudski um. Hoće li ga itko od režimskih medija ikada upitati koristi li, s obzirom na prometni kaos kojemu svjedočimo, svoje znanje u svrhu društvenog inženjeringa?</p>
<p>Vjerojatno ne. Vjerojatno ćemo nastaviti razglabati o njihovim potezima kao da se radi o naivnim glupkastim, ponešto radikalnim, ali dobronamjernim dečkima. Ili ćemo pak, za što ima najviše šanse, jednostavno nastaviti pasivno pristajati na sve što nam se servira, pa kada se jedan dan probudimo i kada, umjesto samo za svoje parkirno mjesto, gradu budemo morali plaćati i za napuštanje svog dodijeljenog bloka, tada ćemo se možda upitati kako je do ovoga došlo. A možda i nećemo. Ako smo već zaboravili segregaciju ogradama od prije koju godinu od tih samoprozvanih boraca za društvenu pravdu, izgledno je da ćemo zaboraviti i buduća poigravanja našim slobodama, gradovima i umovima.</p>
<p>#SapereAude</p>
