INSERT INTO media (id, publication_id, kind, storage_key, filename, mime_type, byte_size) VALUES ('e4d9b8a11365e841bab36ec70479aa02', '4cd630440b929be61d9c36769b788da2', 'image', 'pub/4cd630440b929be61d9c36769b788da2/e4d9b8a11365e841bab36ec70479aa02/iz-globalisticko-progresivne-kuhinje-s.jpg', 'iz-globalisticko-progresivne-kuhinje-s.jpg', 'image/jpeg', 36372);
INSERT INTO posts (id, publication_id, slug, title, subtitle, body_md, body_html, cover_media_id, category_id, kind, status, published_at) VALUES ('215ab93f1d480f67ba2de54b51b5e121', '4cd630440b929be61d9c36769b788da2', 'iz-globalisticko-progresivne-kuhinje-s-ljubavlju', 'DEMO ### 302 Iz globalističko-progresivne kuhinje s ljubavlju', '', '![](https://substackcdn.com/image/fetch/$s_!4DDi!,f_auto,q_auto:good,fl_progressive:steep/https%3A%2F%2Fsubstack-post-media.s3.amazonaws.com%2Fpublic%2Fimages%2Ffb873030-542f-45b2-a6e5-c5cbc4bfb44e_400x400.jpeg)

Nezapamćeni nestanci električne energije paralizirali su veći dio Španjolske i Portugala, ostavivši metroe, zračne luke, tvornice i komunikacijsku infrastrukturu u potpunom kolapsu.

Iako službene izjave govore o "rijetkoj atmosferskoj pojavi", mnogi znakovi upućuju na to da bi mogla biti riječ o još jednoj posljedici iracionalne i ideološki vođene energetske politike kakvu trenutno provodi velik dio progresivne Europe. Španjolska je vlast naime prije samo šest dana proslavila činjenicu da se njihova mreža u potpunosti oslanja na takozvane obnovljive izvore.

Treba imati na umu da krize ovakvih razmjera u suvremenom svijetu rijetko kada nastaju slučajno. Vrijedi se stoga ozbiljno zapitati koliko je ova situacija povezana i s nedavnim preporukama i upozorenjima Europske unije da građani pripreme osnovne potrepštine za izvanredne situacije.

Ostaje za vidjeti hoće li se ovi događaji s vremenom pamtiti kao velike, ali prolazne krize, ili će ih povijest sagledavati kao pripremu za nešto znatno ozbiljnije. U svakom slučaju, nije izvjesno da će itko od naših samozvanih globalističkih i progresivnih upravitelja ovu uznemirujuću epizodu protumačiti kao poziv na odustajanje od daljnje digitalizacije i centralizacije upravljanja našom svakodnevicom.

Ako pak mislimo da nas se ovo ne tiče, podsjetimo se da favorit za nastavak vladavine nad našom metropolom dolazi iz redova stranke koja otvoreno podržava ekofanatičnu politiku poznatu kao "NetZero".

