INSERT INTO media (id, publication_id, kind, storage_key, filename, mime_type, byte_size) VALUES ('6457b2252c888233437ad9c7c4356ce3', '4cd630440b929be61d9c36769b788da2', 'image', 'pub/4cd630440b929be61d9c36769b788da2/6457b2252c888233437ad9c7c4356ce3/gostovanje-u-podcast-mreznici-rastuca.jpg', 'gostovanje-u-podcast-mreznici-rastuca.jpg', 'image/jpeg', 150517);
INSERT INTO posts (id, publication_id, slug, title, subtitle, body_md, body_html, cover_media_id, category_id, kind, status, published_at) VALUES ('652e9630fb7563e14627e32360a9af59', '4cd630440b929be61d9c36769b788da2', 'gostovanje-u-podcast-mreznici-rastuca-globalisticka-tehnokracija', 'DEMO ### 324 Gostovanje u Podcast Mrežnici: rastuća globalistička tehnokracija', '', 'Pod tragičnim plaštom ratnih kriza pojedini centri moći našega društva masovno povećavaju svoj nadzor nad nama kao građanima. Tako je odnedavno na razini Europske unije pred usvajanjem nova regulativa koja će zabraniti korištenje tehnološke enkripcije. 

Radi se o tehnologiji koja štiti naše privatne poruke i podatke od penetracije stranih entiteta, pa i državnih i naddržavnih vlasti. Ukoliko se ta regulativa zaista usvoji, svaku vašu poruku i poslanu fotografiju Europska unija moći će vidjeti prema svojoj volji, bez sudskog naloga i procesa. 

O svemu ovome i mnogočemu drugome govorio sam tijekom svog novog [gostovanja](https://www.youtube.com/watch?v=fcZd-SnaWEA) u podcastu Mrežnica.

![Opis fotografije nije dostupan.](https://substackcdn.com/image/fetch/$s_!ABql!,f_auto,q_auto:good,fl_progressive:steep/https%3A%2F%2Fsubstack-post-media.s3.amazonaws.com%2Fpublic%2Fimages%2F6512e6a6-f161-48fd-98f9-0083d170d4b5_1600x1066.jpeg)

Važno je da svi shvatimo ozbiljnost prijetnje tehnokratskog globalističkog totalitarizma koji svakim danom na Zapadu dobiva sve jasnije obrise. Pozivam vas stoga na gledanje spomenutog podcasta, kojeg prilažem u komentaru. Hvala ekipi iz Mrežnice na hrabrosti progovaranja o ovim temama.

