INSERT INTO media (id, publication_id, kind, storage_key, filename, mime_type, byte_size) VALUES ('3033c68ebc0700101874074d8b7ada81', '4cd630440b929be61d9c36769b788da2', 'image', 'pub/4cd630440b929be61d9c36769b788da2/3033c68ebc0700101874074d8b7ada81/znamo-doista-ako-se-razrusi-nas.png', 'znamo-doista-ako-se-razrusi-nas.png', 'image/png', 156516);
INSERT INTO posts (id, publication_id, slug, title, subtitle, body_md, body_html, cover_media_id, category_id, kind, status, published_at) VALUES ('9ed9a4dc0c4a40ca6c315217e217408b', '4cd630440b929be61d9c36769b788da2', 'pokoj-vjecni-daruj-mu-gospodine', 'DEMO ### 361 Pokoj vječni daruj mu, Gospodine', '', '![](https://substackcdn.com/image/fetch/$s_!xTZm!,f_auto,q_auto:good,fl_progressive:steep/https%3A%2F%2Fsubstack-post-media.s3.amazonaws.com%2Fpublic%2Fimages%2F56600cb2-8386-448b-8121-7c63bce39a68_640x360.png)

"Znamo doista: ako se razruši naš zemaljski dom, šator, imamo zdanje od Boga, dom nerukotvoren, vječan na nebesima."

U razdobljima civilizacijskog urušavanja, u kakvom je sve očitije da se trenutno nalazimo, dužnost je svakoga iskorijeniti iz sebe dekadenciju, laži i pojednostavljene ideologizirane odgovore te se nikada čvršće povezati s Istinom. Dužni smo biti svjetlost u mraku i odraz vječnosti u ovom šatoru grešnosti i prolaznosti. Pa krenimo s time već danas.

Pokoj vječni daruj mu, Gospodine i svjetlost vječna neka nam svima svijetli.', '<p><img src="https://substackcdn.com/image/fetch/$s_!xTZm!,f_auto,q_auto:good,fl_progressive:steep/https%3A%2F%2Fsubstack-post-media.s3.amazonaws.com%2Fpublic%2Fimages%2F56600cb2-8386-448b-8121-7c63bce39a68_640x360.png" alt=""></p>
<p>&quot;Znamo doista: ako se razruši naš zemaljski dom, šator, imamo zdanje od Boga, dom nerukotvoren, vječan na nebesima.&quot;</p>
<p>U razdobljima civilizacijskog urušavanja, u kakvom je sve očitije da se trenutno nalazimo, dužnost je svakoga iskorijeniti iz sebe dekadenciju, laži i pojednostavljene ideologizirane odgovore te se nikada čvršće povezati s Istinom. Dužni smo biti svjetlost u mraku i odraz vječnosti u ovom šatoru grešnosti i prolaznosti. Pa krenimo s time već danas.</p>
<p>Pokoj vječni daruj mu, Gospodine i svjetlost vječna neka nam svima svijetli.</p>
