INSERT INTO media (id, publication_id, kind, storage_key, filename, mime_type, byte_size) VALUES ('ed52610201c1f577215b74c1e715c774', '4cd630440b929be61d9c36769b788da2', 'image', 'pub/4cd630440b929be61d9c36769b788da2/ed52610201c1f577215b74c1e715c774/tomislav-tomasevic-i-izborni-predmet.png', 'tomislav-tomasevic-i-izborni-predmet.png', 'image/png', 43112);
INSERT INTO posts (id, publication_id, slug, title, subtitle, body_md, body_html, cover_media_id, category_id, kind, status, published_at) VALUES ('74b55575acf8181c434201fbc9a20e2e', '4cd630440b929be61d9c36769b788da2', 'tomislav-tomasevic-i-izborni-predmet-seksualne-revolucije', 'DEMO ### 375 Tomislav Tomašević i "izborni predmet" seksualne revolucije', '', '![](https://substackcdn.com/image/fetch/$s_!mQsc!,f_auto,q_auto:good,fl_progressive:steep/https%3A%2F%2Fsubstack-post-media.s3.amazonaws.com%2Fpublic%2Fimages%2Fdb7e37bb-3ae6-465c-a5a8-221a81aa22f8_640x360.png)

Tomislav Tomašević zasigurno je čuo i vidio da je jedna od osoba zaduženih za osmišljavanje tzv. seksualne edukacije na snimkama govorila o destigmatizaciji pedofilije te o „normalnosti“ dječje masturbacije. Ipak, jedino što smo od plahog gradonačelnika čuli o tome jest da će ta, kako kaže, edukacija biti izborni predmet. Time se zagrebačkim roditeljima zapravo poručuje kako će Zagreb postati grad koji na radikalne seksualnorevolucionarne eksperimente gleda kao na nešto što se može izabrati poput bilo kojeg drugog legitimnog sadržaja — primjerice odluke hoće li nam djeca ići na sport ili u glazbenu školu. 

Upravo takav stav daje legitimaciju jezivim, hiperseksualiziranim sadržajima kakvih je suvremeni Zapad prepun, gdje se na istu razinu svodi tisućljećima građeni spolni, ali i svaki drugi moral, te poticanje djece na masturbaciju.

Dakako, svima koji ne kroje svoja mišljenja intelektualno zatupljenim mantranjem teza iz glavnostrujaških medija jasno je da radikalni seksualnorevolucionarni sadržaji čine štetu svakom pojedincu, pa i cjelini gradske zajednice neovisno o njihovoj "izbornosti", jer perpetuiranje spolnog amorala djeluje kao društvena zaraza, što čak i znanstvena literatura jasno pokazuje. Lisa Littman, primjerice, pokazala je kako se gotovo 90% slučajeva takozvane rodne disforije javlja nakon što je već netko ranije iz razreda ili škole pokazivao te znakove, odnosno u klasterima s drugom djecom.

U sveopćem ciljanom kaosu koji su progresivne struje stvorile kako bi, uobičajenim metodama koje smo gledali i drugdje na Zapadu, pročistile prostor za nametanje eksperimentalnog, iznimno štetnog sadržaja, vratimo se jednostavnim činjenicama.

Zagrebački vam je gradonačelnik upravo rekao da će dio zagrebačke djece, pod njegovim pokroviteljstvom, moći slušati sadržaje među ostalim bazirane na prokazano mračnim, pa i punokrvno pedofilskim misliocima kao što je Alfred Kinsey. On je, prema potresnim svjedočanstvima, sredinom prošloga stoljeća plaćao roditeljima da diraju svoju djecu te mu javljaju rezultate za njegova istraživanja. Na njegov institut takozvani se seksualni edukatori u javnosti kontinuirano pozivaju, što razni njihovi nastupi jasno pokazuju usprkos njihovom paničnom uklanjanju s interneta posljednjih dana.

Ako ste se pitali kako su se Amerika, Velika Britanija i Kanada dovele u situaciju u kojoj se roditelji privode kada odbijaju davati hormonske tretmane svojoj djeci u ime eksperimentalnih terapija, na primjeru Zagreba sada možete vidjeti kako: postupnim i suptilnim osvajanjem terena, uz masovnu pomoć glavnostrujaške medijske mašinerije.

#SapereAude', '<p><img src="https://substackcdn.com/image/fetch/$s_!mQsc!,f_auto,q_auto:good,fl_progressive:steep/https%3A%2F%2Fsubstack-post-media.s3.amazonaws.com%2Fpublic%2Fimages%2Fdb7e37bb-3ae6-465c-a5a8-221a81aa22f8_640x360.png" alt=""></p>
