INSERT INTO media (id, publication_id, kind, storage_key, filename, mime_type, byte_size) VALUES ('da17d9d4aa633831c704bffb730fbe11', '4cd630440b929be61d9c36769b788da2', 'image', 'pub/4cd630440b929be61d9c36769b788da2/da17d9d4aa633831c704bffb730fbe11/veliki-intervju-za-narodhr.jpg', 'veliki-intervju-za-narodhr.jpg', 'image/jpeg', 81754);
INSERT INTO posts (id, publication_id, slug, title, subtitle, body_md, body_html, cover_media_id, category_id, kind, status, published_at) VALUES ('cb0986f250d4f5092053180fe63e0cb7', '4cd630440b929be61d9c36769b788da2', 'veliki-intervju-za-narod-hr', 'DEMO ### 376 Veliki intervju za Narod.hr', '', 'Pozivam vas da pročitate veliki [intervju](https://narod.hr/hrvatska/intervju-s-lukom-golesom-babicem-novim-licem-na-konzervativnoj-sceni-lgbtiq-odbacuje-logos-pa-tako-i-dijalog) koji sam dao za Narod.hr. U njemu sam još jednom predstavio svoj javni rad i buduće planove te razjasnio što me motiviralo da se uključim u tinjajuće kulturne ratove.

Također sam se detaljno osvrnuo na aktivne bojišnice tih ratova, među kojima je i tzv. seksualna edukacija, ali i općenito plansko labavljenje tisućljećima građenog spolnog morala, kako bi se u pogubljenoj osobi posljedično mogle usaditi “novonormalne” progresivne dogme.

Razgovarali smo i o mnogim drugim temama, pa i o mojim političkim ambicijama.

![](https://substackcdn.com/image/fetch/$s_!QmGg!,f_auto,q_auto:good,fl_progressive:steep/https%3A%2F%2Fsubstack-post-media.s3.amazonaws.com%2Fpublic%2Fimages%2F0ce4d5c0-5331-4134-8436-d60c0d74e456_992x812.png)

Ovim putem za intervju još jednom zahvaljujem Luki Šariću, hrabrom kulturnom i civilizacijskom suborcu.

#SapereAude', '<p>Pozivam vas da pročitate veliki <a href="https://narod.hr/hrvatska/intervju-s-lukom-golesom-babicem-novim-licem-na-konzervativnoj-sceni-lgbtiq-odbacuje-logos-pa-tako-i-dijalog">intervju</a> koji sam dao za Narod.hr. U njemu sam još jednom predstavio svoj javni rad i buduće planove te razjasnio što me motiviralo da se uključim u tinjajuće kulturne ratove.</p>
<p>Također sam se detaljno osvrnuo na aktivne bojišnice tih ratova, među kojima je i tzv. seksualna edukacija, ali i općenito plansko labavljenje tisućljećima građenog spolnog morala, kako bi se u pogubljenoj osobi posljedično mogle usaditi “novonormalne” progresivne dogme.</p>
<p>Razgovarali smo i o mnogim drugim temama, pa i o mojim političkim ambicijama.</p>
<p><img src="https://substackcdn.com/image/fetch/$s_!QmGg!,f_auto,q_auto:good,fl_progressive:steep/https%3A%2F%2Fsubstack-post-media.s3.amazonaws.com%2Fpublic%2Fimages%2F0ce4d5c0-5331-4134-8436-d60c0d74e456_992x812.png" alt=""></p>
<p>Ovim putem za intervju još jednom zahvaljujem Luki Šariću, hrabrom kulturnom i civilizacijskom suborcu.</p>
