INSERT INTO media (id, publication_id, kind, storage_key, filename, mime_type, byte_size) VALUES ('fba9832c053873e6cb1c6c7bc985e2ce', '4cd630440b929be61d9c36769b788da2', 'image', 'pub/4cd630440b929be61d9c36769b788da2/fba9832c053873e6cb1c6c7bc985e2ce/poziv-na-panel.jpg', 'poziv-na-panel.jpg', 'image/jpeg', 55966);
INSERT INTO posts (id, publication_id, slug, title, subtitle, body_md, body_html, cover_media_id, category_id, kind, status, published_at) VALUES ('283d9c964fc3edae42f18d6fcf700f75', '4cd630440b929be61d9c36769b788da2', 'poziv-na-panel', 'DEMO ### 381 Poziv na panel', '', '![](https://substackcdn.com/image/fetch/$s_!674_!,f_auto,q_auto:good,fl_progressive:steep/https%3A%2F%2Fsubstack-post-media.s3.amazonaws.com%2Fpublic%2Fimages%2Fde57febd-9de0-445b-9ed9-b5f3be421ccf_331x466.jpeg)

Europska unija kakvu danas poznajemo pervertirala je izvorne ideje na kojima je nastala. Njezini idejni začetnici, mnogi od njih katolički intelektualci, zamišljali su Uniju kao zajednicu okupljenu oko naravnih vrijednosti – ili, riječima Václava Havela, oko metafizičke odgovornosti i uzvišenih, trajnih načela. 

Ona je međutim prošla put raščarenja: prvo je transformirana iz zajednice okupljene oko transcendentnosti u ekonomsku zajednicu, a potom iz ekonomske zajednice u zajednicu okupljenu oko radikalno progresivnih, protunaravnih umotvorina koje se nameću sve otvorenijim protudemokratskim metodama. Mnogi povijesni mislioci, pa tako i ja, pišu o tehnototalitarnom režimu koji nam predstoji, a koji upravo radom mreže bezličnih eurokratskih birokrata dobiva sve jasnije obličje.

Može li se Europska unija ponovno oblikovati u nešto smisleno, ukorijenjeno u vječnost, umjesto u prolazne, frankenstajnovske zamisli jednog moralno iskrivljenog doba? Ili neman koja je nastala pod kišobranom pojma Unije jednostavno treba raspustiti? Ta pitanja, i mnoga druga, raspravit ću u četvrtak, 30. listopada u 20:00 sati, u Ilici 10 (drugi kat), na panelu sa zastupnikom u Europskom parlamentu Stjepom Bartulicom.

Ulaz je slobodan, stoga se nadam da ćemo se vidjeti u što većem broju.

#SapereAude', '<p><img src="https://substackcdn.com/image/fetch/$s_!674_!,f_auto,q_auto:good,fl_progressive:steep/https%3A%2F%2Fsubstack-post-media.s3.amazonaws.com%2Fpublic%2Fimages%2Fde57febd-9de0-445b-9ed9-b5f3be421ccf_331x466.jpeg" alt=""></p>
<p>Europska unija kakvu danas poznajemo pervertirala je izvorne ideje na kojima je nastala. Njezini idejni začetnici, mnogi od njih katolički intelektualci, zamišljali su Uniju kao zajednicu okupljenu oko naravnih vrijednosti – ili, riječima Václava Havela, oko metafizičke odgovornosti i uzvišenih, trajnih načela. </p>
<p>Ona je međutim prošla put raščarenja: prvo je transformirana iz zajednice okupljene oko transcendentnosti u ekonomsku zajednicu, a potom iz ekonomske zajednice u zajednicu okupljenu oko radikalno progresivnih, protunaravnih umotvorina koje se nameću sve otvorenijim protudemokratskim metodama. Mnogi povijesni mislioci, pa tako i ja, pišu o tehnototalitarnom režimu koji nam predstoji, a koji upravo radom mreže bezličnih eurokratskih birokrata dobiva sve jasnije obličje.</p>
<p>Može li se Europska unija ponovno oblikovati u nešto smisleno, ukorijenjeno u vječnost, umjesto u prolazne, frankenstajnovske zamisli jednog moralno iskrivljenog doba? Ili neman koja je nastala pod kišobranom pojma Unije jednostavno treba raspustiti? Ta pitanja, i mnoga druga, raspravit ću u četvrtak, 30. listopada u 20:00 sati, u Ilici 10 (drugi kat), na panelu sa zastupnikom u Europskom parlamentu Stjepom Bartulicom.</p>
<p>Ulaz je slobodan, stoga se nadam da ćemo se vidjeti u što većem broju.</p>
<p>#SapereAude</p>
', 'fba9832c053873e6cb1c6c7bc985e2ce', '6aae657f04b4f6e83eb50e5df53cee70', 'post', 'published', '2025-10-28T13:14:00.000Z');
INSERT INTO posts (id, publication_id, slug, title, subtitle, body_md, body_html, cover_media_id, category_id, kind, status, published_at) VALUES ('19dda8277b3e431ab9cee3156bf6249f', '4cd630440b929be61d9c36769b788da2', 'mentalno-zdravlje-u-doba-kolektivnog-poricanja', 'DEMO ### 382 Mentalno zdravlje u doba kolektivnog poricanja', '', '![](https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEhoxvi17_qgCdZlidE73wdducjvXsa9ZTNaiZrg7Kr-2fXWA5vqL2dfNKEBoyAq0S2PGnmHV98qBaWmgypiIkmav2dEnsuQuw83jijsz51FapWZgTMlNwRtb1lE9KZKsrKtCfhLll6Kw7LUe8F2Vc98C6liy7P_2Dme5_ahiMWLSmi_EbPQuPlU450LuWc/s1071/76c3c8c6-37dd-46c1-8bff-7787adb0770c.jpg)

Kada god čujemo nekog vojnika glavnostrujaške mašine – bio on političar, „stručnjak“ ili novinar – da laprda o važnosti mentalnog zdravlja djece i mladih ili o nužnosti detehnologizacije škola, moramo se, kao Pavlovljevim refleksom, prisjetiti što je ista ta mašina činila djeci prije manje od tri godine.

Od 2020. do 2023. svijetom je naime vladao jedan bezpresedanski globalistički tehnokratski sustav u kojem je naša egzistencija bila uvjetovana poslušnošću raznim tehnologijama, mnoge od kojih su bile potpuno nove, a mahnito i agresivno nametane svakome. Tada smo prošli kroz svojevrsni biotehnološki i psihosocijalni globalni eksperiment povijesnih razmjera, a možda najveća žrtva svega toga bile su upravo najosjetljivije skupine našeg društva, odnosno djeca i pojedinci starije životne dobi.

Djeca, o čijem se mentalnom zdravlju danas obredno raspravlja u saborskim prostorijama i medijskim redakcijama, tada su bila žrtvovana na oltaru naših „javnozdravstvenih“ rituala, tako što su svoje izgradbene godine bila prisiljena provoditi zatvorena u domovima, pred ekranima, bez sporta, bez socijalizacije i bez općenitog međuljudskog kontakta. Neki od nas koji su te duge tri godine grmjeli o opasnostima hipnotiziranog hiperfokusa na jedan, danas znamo, iznimno sumnjivi virus, bili su nazivani uobičajenom plejadom liberalnih i tolerantnih epiteta naših progresivnih civilizacijskih susjeda.

Danas su pak istim tim novodogmatičnim nasilnicima puna usta važnosti pluralizma, mentalnog zdravlja i – ni manje ni više nego – borbe s toksičnim ponašanjem u digitalnoj sferi. Stalo vam je do mentalnog zdravlja djece? Pozabavite se odgovornima za to što su djeca bila bombardirana svakodnevnim sijanjem panike, prijetnjama kako će ubiti svoje bake i općenitom dobro osmišljenom neviđeno toksičnom propagandom. Brinete o mobitelima u školama? Zapitajte se tko je i zašto između učitelja i učenika te između školskih prijatelja na duge tri godine stavio ekrane, time otimajući pojedinoj djeci većinu njihova srednjoškolskog obrazovanja.

Njihovo laprdanje o mentalnom zdravlju janjeća je koža kojom skrivaju svoje prave namjere, koje se od razdoblja spomenute globalne hipnoze do danas uopće nisu ublažile, štoviše, samo su u pozadini dobivale sve monstruoznije gabarite. I ne – neki od nas nikada neće zaboraviti što se tada činilo, pa koliko god se glavnostrujaška mašina trudila propagirati masovnu amneziju.

#SapereAude', '<p><img src="https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEhoxvi17_qgCdZlidE73wdducjvXsa9ZTNaiZrg7Kr-2fXWA5vqL2dfNKEBoyAq0S2PGnmHV98qBaWmgypiIkmav2dEnsuQuw83jijsz51FapWZgTMlNwRtb1lE9KZKsrKtCfhLll6Kw7LUe8F2Vc98C6liy7P_2Dme5_ahiMWLSmi_EbPQuPlU450LuWc/s1071/76c3c8c6-37dd-46c1-8bff-7787adb0770c.jpg" alt=""></p>
