INSERT INTO media (id, publication_id, kind, storage_key, filename, mime_type, byte_size) VALUES ('d0eb9222feade4b81bfffb018329db33', '4cd630440b929be61d9c36769b788da2', 'image', 'pub/4cd630440b929be61d9c36769b788da2/d0eb9222feade4b81bfffb018329db33/divide-et-impera-i-kako-segregacija.jpg', 'divide-et-impera-i-kako-segregacija.jpg', 'image/jpeg', 43321);
INSERT INTO posts (id, publication_id, slug, title, subtitle, body_md, body_html, cover_media_id, category_id, kind, status, published_at) VALUES ('2129cb93c73bd5f4382e4f075363e65e', '4cd630440b929be61d9c36769b788da2', 'divide-et-impera-i-kako-segregacija-preko-noci-moze-postati-slobodom', 'DEMO ### 390 Divide et impera i kako segregacija preko noći može postati slobodom', '', '![](https://substackcdn.com/image/fetch/$s_!KnNT!,f_auto,q_auto:good,fl_progressive:steep/https%3A%2F%2Fsubstack-post-media.s3.amazonaws.com%2Fpublic%2Fimages%2F415c5a7b-3aba-421c-8922-1572346c9a0f_400x400.jpeg)

Činjenica da će na Interliberu neki štandovi biti označeni kao „mjesta slobode“ mikroprimjer je ritualiziranog i parareligijskog momenta suvremenog, progresivizmom natopljenog društva. Naime, i više je nego ironično što upravo organizator Interlibera pristaje na ovakve manipulativne inicijative moralno kamatarskih progresivnih udruga, imajući na umu da je isti taj Interliber prije samo nekoliko godina revno primjenjivao najveći segregacijski alat u povijesti demokratske Hrvatske.

Nakon poslušnog korištenja takozvanih pandemijskih potvrda, za koje danas znamo da nisu bile utemeljene ni na čemu osim na psihosocijalnom globalističkom eksperimentiranju, pa stoga ni ne mogu biti ništa drugo doli sredstvo segregacije, čovjek bi očekivao da će organizator Interlibera imati barem trunku samopoštovanja te da se neće sramotiti glumeći borca za slobodu mišljenja, izražavanja i okupljanja – svega onoga što je donedavno sam ograničavao.

Ako ste vi, gospodo, zaboravili, mi nismo: ni masovnu cenzuru na društvenim mrežama, ni uvrede, prijetnje, ucjene, gubitke poslova, tužbe, razdvajanja obitelji, pa ni zabrane posjeta najbližima u bolnicama i domovima za starije. 

Andrija Klarić je prije nekoliko tjedana dobio službenu presudu prema kojoj mora platiti nekoliko tisuća eura kazne zato što se na prosvjedu, koji je organizirao kako bi se demokratski suprotstavio takozvanim mjerama, nisu poštovale iste te mjere. A sada njemu upravo ti segregatori i razne pseudomoralizirajuće udruge, s dokazanim renomeom totalitarnog refleksa, ritualno trube o tome kako su njihovi štandovi „mjesta slobode“.

Dakako, ova objava nije upućena njima. Oni vrlo dobro znaju što rade, i to rade svjesno, u skladu s poznatom strategijom divide et impera. Samo što se, umjesto zamišljene rasne mržnje u Americi ili orkestrirane seksualne mržnje u Mađarskoj, kod nas potiče ustaško-partizanska mržnja, parazitiranjem na otvorenim ranama ovog napaćenog naroda.

Ova je dakle poruka upućena svima ostalima: ne nasjedajte na obredne spirale agresije koje nam se posljednjih tjedana planski nameću.

#SapereAude', '<p><img src="https://substackcdn.com/image/fetch/$s_!KnNT!,f_auto,q_auto:good,fl_progressive:steep/https%3A%2F%2Fsubstack-post-media.s3.amazonaws.com%2Fpublic%2Fimages%2F415c5a7b-3aba-421c-8922-1572346c9a0f_400x400.jpeg" alt=""></p>
