INSERT INTO media (id, publication_id, kind, storage_key, filename, mime_type, byte_size) VALUES ('94798f38d6e7ccf43b7cf703ab71a3cc', '4cd630440b929be61d9c36769b788da2', 'image', 'pub/4cd630440b929be61d9c36769b788da2/94798f38d6e7ccf43b7cf703ab71a3cc/o-portalu.jpg', 'o-portalu.jpg', 'image/jpeg', 169051);
INSERT INTO posts (id, publication_id, slug, title, subtitle, body_md, body_html, cover_media_id, category_id, kind, status, published_at) VALUES ('979abffe31f3365e71fad29cd40bd005', '4cd630440b929be61d9c36769b788da2', 'o-nama', 'DEMO ### 391 O nama', '', '**Sapere Aude** *(lat. Usudi se misliti)* je intelektualno-aktivistički e-časopis posvećen kritičkom propitivanju filozofskih, kulturnih i duhovnih nedostataka suvremenog društva te obrani i afirmaciji klasične zapadne tradicije. Naša je misija probuditi modernog čovjeka iz letargije uvjetovane mahnito progresivnim i intelektualno lijenim vremenima, nudeći argumentirani otpor silama koje ugrožavaju same temelje naše civilizacije.

Platforma donosi eseje, polemičke tekstove, umjetničke kritike i pamflete, kao i sudjelovanja u emisijama, podcastima i tribinama humanističkog sadržaja. Kroz više stotina dosad objavljenih radova nastojimo potaknuti dublje razumijevanje i raspravu o temama koje oblikuju našu kulturu i identitet.

**Sapere Aude** je 2021. godine utemeljio Luka Goleš Babić, inženjer informacijskih tehnologija, filozof i kolumnist, rođen u Zagrebu 1997. godine.

![](https://substackcdn.com/image/fetch/$s_!jB4B!,f_auto,q_auto:good,fl_progressive:steep/https%3A%2F%2Fsubstack-post-media.s3.amazonaws.com%2Fpublic%2Fimages%2F96d882cc-b37d-42df-a341-d0b5a2003aa1_1184x934.jpeg)', '<p><strong>Sapere Aude</strong> <em>(lat. Usudi se misliti)</em> je intelektualno-aktivistički e-časopis posvećen kritičkom propitivanju filozofskih, kulturnih i duhovnih nedostataka suvremenog društva te obrani i afirmaciji klasične zapadne tradicije. Naša je misija probuditi modernog čovjeka iz letargije uvjetovane mahnito progresivnim i intelektualno lijenim vremenima, nudeći argumentirani otpor silama koje ugrožavaju same temelje naše civilizacije.</p>
<p>Platforma donosi eseje, polemičke tekstove, umjetničke kritike i pamflete, kao i sudjelovanja u emisijama, podcastima i tribinama humanističkog sadržaja. Kroz više stotina dosad objavljenih radova nastojimo potaknuti dublje razumijevanje i raspravu o temama koje oblikuju našu kulturu i identitet.</p>
<p><strong>Sapere Aude</strong> je 2021. godine utemeljio Luka Goleš Babić, inženjer informacijskih tehnologija, filozof i kolumnist, rođen u Zagrebu 1997. godine.</p>
<p><img src="https://substackcdn.com/image/fetch/$s_!jB4B!,f_auto,q_auto:good,fl_progressive:steep/https%3A%2F%2Fsubstack-post-media.s3.amazonaws.com%2Fpublic%2Fimages%2F96d882cc-b37d-42df-a341-d0b5a2003aa1_1184x934.jpeg" alt=""></p>
