INSERT INTO media (id, publication_id, kind, storage_key, filename, mime_type, byte_size) VALUES ('6142b10ab66faa5d448e655836045d57', '4cd630440b929be61d9c36769b788da2', 'image', 'pub/4cd630440b929be61d9c36769b788da2/6142b10ab66faa5d448e655836045d57/kratki-osvrt-na-snizene-kriterije.jpg', 'kratki-osvrt-na-snizene-kriterije.jpg', 'image/jpeg', 79152);
INSERT INTO posts (id, publication_id, slug, title, subtitle, body_md, body_html, cover_media_id, category_id, kind, status, published_at) VALUES ('1586b99e1c8e62d5cc09cb2462926e96', '4cd630440b929be61d9c36769b788da2', 'kratki-osvrt-na-snizene-kriterije-hrvatske-desnice', 'DEMO ### 392 Kratki osvrt na snižene kriterije hrvatske desnice', '', 'Velik dio hrvatske desnice ponaša se poput djeteta na školskom igralištu koje godinama trpi zlostavljanje, pa svaku sitnicu; svaki osmijeh ili lijepu riječ svog zlostavljača, doživljava kao znak pomirenja i prijateljstva. Možda me godinama gurao, rušio i ismijavao, ali danas mi je na nekoliko minuta posudio loptu pa mu sve opraštam.

Tako otprilike izgleda kada konzervativci posljednjih dana hvale premijera te pristaju na njegov igrokaz u kojemu preuzima ulogu naglo probuđenog konzervativca i domoljuba. Plenković se naime jučer snebivao nad licemjerjem “ljevice”, koja brani domoljubne koncerte, a istovremeno puni gradove svojim znakovljem i pseudozastavama.

![](https://substackcdn.com/image/fetch/$s_!zXkr!,f_auto,q_auto:good,fl_progressive:steep/https%3A%2F%2Fsubstack-post-media.s3.amazonaws.com%2Fpublic%2Fimages%2F4ad5ba2a-04da-4679-a05b-c85aa182c80a_1640x924.png)

Desnica je očito toliko emaskulirana da ih svega nekoliko mrvica bačenih sa stola njihovog globalistički i progresivno nastrojenog tlačitelja može zadovoljiti. Radi tih mrvica ona naglo zaboravlja da je isti taj premijer uveo Istanbulsku konvenciju, koja služi kao pravni okvir nametanja svih onih progresivnih i seksualnorevolucionarnih politika s kojima se mi i naša djeca danas suočavamo. Zaboravlja da je svaki HDZ-ov europarlamentarac prije manje od pet godina glasao za to da EU postane LGBTIQ zona. Zaboravlja da HDZ sustavno mijenja sliku Hrvatske masovnim migracijama. Zaboravlja da upravo oni tisućama eura godišnje financiraju otvoreno protuhrvatski nastrojene časopise, udruge i medije.

Suvišno je nadalje govoriti o hadezeovim krimenima i o tome zašto oni nikada više ne zaslužuju biti smatrani konzervativnom, a kamoli demokršćanskom strankom. Kome to nije jasno, taj nije pratio na nastavi civilizacijskih previranja. Neka se radije baci na čitanje Sapere Aude tekstove od posljednjih godina; u njima će pronaći mnogo konkretnije, dublje i sveobuhvatnije kritike globalističko-progresivnog projekta od jučerašnjeg oportunističkog lažnodomoljubnog prenemaganja.

Gorka tableta današnjeg dana jest sljedeća: za našu slabašnu vjeru, za naš narušeni moralni kompas i za naše nevjerojatno spuštene kriterije nisu krivi ni Srbi ni komunisti ni kulturna hegemonija ljevice. Krivi su prvenstveno oni među nama koji na takvo stanje pristaju.

