INSERT INTO media (id, publication_id, kind, storage_key, filename, mime_type, byte_size) VALUES ('d243534b1e52f595d844d5f98b222270', '4cd630440b929be61d9c36769b788da2', 'image', 'pub/4cd630440b929be61d9c36769b788da2/d243534b1e52f595d844d5f98b222270/priopcenje-o-fact-checkingu-i-novim.jpg', 'priopcenje-o-fact-checkingu-i-novim.jpg', 'image/jpeg', 245525);
INSERT INTO posts (id, publication_id, slug, title, subtitle, body_md, body_html, cover_media_id, category_id, kind, status, published_at) VALUES ('be0dd37e32696b5d831980db1bc2a6a0', '4cd630440b929be61d9c36769b788da2', 'priopcenje-o-fact-checkingu-i-novim-eu-regulativama', 'DEMO ### 406 Priopćenje o fact-checkingu i novim EU regulativama', 'Savjet za tehnoetiku i antitotalitarizam', '![](https://substackcdn.com/image/fetch/$s_!Rwra!,f_auto,q_auto:good,fl_progressive:steep/https%3A%2F%2Fsubstack-post-media.s3.amazonaws.com%2Fpublic%2Fimages%2F911b0ad3-2542-42a3-8f46-5110d97bc15c_2048x1152.jpeg)

[Savjet za tehnoetiku i antitotalitarizam](https://tehnoetika.substack.com/), zajedno s Mostovim zastupnicima, 12. prosinca održao je konferenciju za medije i predstavio novo [priopćenje](https://tehnoetika.substack.com/p/priopcenje-o-fact-checkingu-i-novim) o ulozi fact-checkera te utjecaju novih DSA i EMFA regulativa na slobodu govora i medijski pluralizam u Europi.

U priopćenju Savjet upozorava na sve izraženiji trend tehnokratskog upravljanja, u kojem se javni prostor filtrira kroz mrežu regulatornih tijela, tehnoloških korporacija i tzv. “povjerljivih tragača za dezinformacijama”.

Posebna pažnja posvećena je problemu navodne neovisnosti fact-checkera, osobito kada su financirani sredstvima institucija čiji rad trebaju nadzirati.

*Medijsko obraćanje:*

https://www.youtube.com/watch?v=qkSRFkElpS4', '<p><img src="https://substackcdn.com/image/fetch/$s_!Rwra!,f_auto,q_auto:good,fl_progressive:steep/https%3A%2F%2Fsubstack-post-media.s3.amazonaws.com%2Fpublic%2Fimages%2F911b0ad3-2542-42a3-8f46-5110d97bc15c_2048x1152.jpeg" alt=""></p>
