INSERT INTO media (id, publication_id, kind, storage_key, filename, mime_type, byte_size) VALUES ('7346eb41c9269227984de8d7953dfe21', '4cd630440b929be61d9c36769b788da2', 'image', 'pub/4cd630440b929be61d9c36769b788da2/7346eb41c9269227984de8d7953dfe21/osvrt-na-emisiju-fenomen-tjedna.jpg', 'osvrt-na-emisiju-fenomen-tjedna.jpg', 'image/jpeg', 107291);
INSERT INTO posts (id, publication_id, slug, title, subtitle, body_md, body_html, cover_media_id, category_id, kind, status, published_at) VALUES ('f87653047033dcbd5f288e61dc047420', '4cd630440b929be61d9c36769b788da2', 'osvrt-na-emisiju-fenomen-tjedna', 'DEMO ### 421 Osvrt na emisiju Fenomen tjedna', '', '![](https://substackcdn.com/image/fetch/$s_!XKbX!,f_auto,q_auto:good,fl_progressive:steep/https%3A%2F%2Fsubstack-post-media.s3.amazonaws.com%2Fpublic%2Fimages%2F73b4e4ca-0bac-4fd8-b2e2-fb8c587e74c0_2340x1080.jpeg)

Zahvaljujem svojim večerašnjim sugovornicima u emisiji Fenomen tjedna na uloženom vremenu. Iako je našem razgovoru s intelektualne strane nedostajalo argumentativne preciznosti i opće debatno-logičke discipline, nemajte iluzija: večeras smo na kulturan i pristojan način, bez podizanja glasa na tuđe podizanje glasa, izravno iz srpskih kulturnih centara dobili nekoliko važnih priznanja:

1\. Republika Hrvatska devedesetih je vodila potpuno pravedan, obrambeni rat, za koji ima puno pravo tražiti ratnu odštetu i informacije o nestalima.

2\. Pojedini novinari Novosti, barem deklarativno, nazvali su se hrvatskim patriotima.

3\. Jugoslavenska, amoralna država natopljena komunističkim jednoumljem morala je propasti.

4\. Srpskim tzv. centrima kulture u Hrvatskoj uistinu nedostaje kulture.

Ovim putem apeliram na redakciju Novosti da ove zaključke, koji su jasno artikulirani ispod raznih tema u koje smo samo parcijalno uronili, uprizori u službenom priopćenju, kako bi hrvatsko-srpski odnosi doista mogli krenuti prema poboljšanju. Pomirenja bez istine ne može biti, a s istinom dolazimo do caritas in veritate.

Oni koji su možebitno očekivali moje nadvikavanje ili subintelektualno obračunavanje očito ne prate moj rad i ovu stranicu. Sapere aude se, naime, ne valja u blatu. Poruka upućena Srpskom narodnom vijeću univerzalna je poruka: kultivirajmo se i uzdignimo svoj duh.

#SapereAude', '<p><img src="https://substackcdn.com/image/fetch/$s_!XKbX!,f_auto,q_auto:good,fl_progressive:steep/https%3A%2F%2Fsubstack-post-media.s3.amazonaws.com%2Fpublic%2Fimages%2F73b4e4ca-0bac-4fd8-b2e2-fb8c587e74c0_2340x1080.jpeg" alt=""></p>
