INSERT INTO media (id, publication_id, kind, storage_key, filename, mime_type, byte_size) VALUES ('27540d4b8f0ac6aab929b9e328001dc7', '4cd630440b929be61d9c36769b788da2', 'image', 'pub/4cd630440b929be61d9c36769b788da2/27540d4b8f0ac6aab929b9e328001dc7/konferencija-o-buducnosti-eu-i-tehnokraciji.jpg', 'konferencija-o-buducnosti-eu-i-tehnokraciji.jpg', 'image/jpeg', 373312);
INSERT INTO posts (id, publication_id, slug, title, subtitle, body_md, body_html, cover_media_id, category_id, kind, status, published_at) VALUES ('a2498f94eeb6beb37b78155d7b1ea21b', '4cd630440b929be61d9c36769b788da2', 'konferencija-o-buducnosti-eu-i-tehnokraciji', 'DEMO ### 430 Konferencija o budućnosti EU i tehnokraciji', '24.1.2026. | Rezime', 'U subotu, 24. siječnja, u Hotelu Dubrovnik održali smo konferenciju "Budućnost EU: Uspon tehnokratskog totalitarizma?".

Nakon pojedinačnih izlaganja zastupnika Bartulice, mene i Andrije Klarića, u kojima je svatko iz svog ugla problematizirao aktualni tehnokratski i protuljudski smjer Europske unije, stručni paneli, s nastupima dr. Branimira Pervana i Petra Šarića potvrdili su opravdanost naših briga.

Apostrofirat ću još jednom: ne živimo u vremenu ideologija, već u vremenu rastuće globalističke, postideološke pustoši. Neka ova konferencija posluži kao jasna poruka tehnokratima da mnogi među nama shvaćaju njihove namjere te da na njih nikada neće pristati, ali i kao dimni signal svima kojima je i dalje stalo do njihove tradicije, kulture, vjere, običaja i ukorijenjenog načina življenja.

Ili ćemo se trgnuti iz drijemeža ili ćemo postati upravo onakve programibilne, vrijednosno šuplje tabule rase kakvima nas bezlični eurokratski stroj želi načiniti.

Hvala zastupniku Bartulici i njegovoj ECR grupaciji na suorganizaciji konferencije te svima na nastupu i dolasku. Snimka cijele konferencije bit će objavljena na YouTube kanalu zastupnika Bartulice.

#SapereAude', '<p>U subotu, 24. siječnja, u Hotelu Dubrovnik održali smo konferenciju &quot;Budućnost EU: Uspon tehnokratskog totalitarizma?&quot;.</p>
<p>Nakon pojedinačnih izlaganja zastupnika Bartulice, mene i Andrije Klarića, u kojima je svatko iz svog ugla problematizirao aktualni tehnokratski i protuljudski smjer Europske unije, stručni paneli, s nastupima dr. Branimira Pervana i Petra Šarića potvrdili su opravdanost naših briga.</p>
<p>Apostrofirat ću još jednom: ne živimo u vremenu ideologija, već u vremenu rastuće globalističke, postideološke pustoši. Neka ova konferencija posluži kao jasna poruka tehnokratima da mnogi među nama shvaćaju njihove namjere te da na njih nikada neće pristati, ali i kao dimni signal svima kojima je i dalje stalo do njihove tradicije, kulture, vjere, običaja i ukorijenjenog načina življenja.</p>
<p>Ili ćemo se trgnuti iz drijemeža ili ćemo postati upravo onakve programibilne, vrijednosno šuplje tabule rase kakvima nas bezlični eurokratski stroj želi načiniti.</p>
<p>Hvala zastupniku Bartulici i njegovoj ECR grupaciji na suorganizaciji konferencije te svima na nastupu i dolasku. Snimka cijele konferencije bit će objavljena na YouTube kanalu zastupnika Bartulice.</p>
<p>#SapereAude</p>
', '27540d4b8f0ac6aab929b9e328001dc7', '6aae657f04b4f6e83eb50e5df53cee70', 'post', 'published', '2026-01-30T17:29:02.723Z');
