INSERT INTO media (id, publication_id, kind, storage_key, filename, mime_type, byte_size) VALUES ('8dff43b20fe9622b8a8ed63e041ca3ed', '4cd630440b929be61d9c36769b788da2', 'image', 'pub/4cd630440b929be61d9c36769b788da2/8dff43b20fe9622b8a8ed63e041ca3ed/gostovanje-u-emisiji-kozmos-i-etos.jpg', 'gostovanje-u-emisiji-kozmos-i-etos.jpg', 'image/jpeg', 89453);
INSERT INTO posts (id, publication_id, slug, title, subtitle, body_md, body_html, cover_media_id, category_id, kind, status, published_at) VALUES ('a9ee9b790ea7f6051260c50169563e16', '4cd630440b929be61d9c36769b788da2', 'gostovanje-u-emisiji-kozmos-i-etos-filozofija-richarda-weavera', 'DEMO ### 436 Gostovanje u emisiji Kozmos i etos: filozofija Richarda Weavera', '', '![Richard Weaver on toughness and heroism — Jordan M. Poss](https://substackcdn.com/image/fetch/$s_!e22i!,f_auto,q_auto:good,fl_progressive:steep/https%3A%2F%2Fsubstack-post-media.s3.amazonaws.com%2Fpublic%2Fimages%2F50fc8481-d606-4eaa-a7f5-a7796dc09303_639x941.jpeg)

Sutra u 9 sati gostujem u filozofskoj emisiji *Kozmos i eto*s, koju možete poslušati na Trećem programu Hrvatskoga radija (HRT 3).

Tema je moj esej “Veliki stereoptikon masovnih medija”, objavljen u siječnju u znanstvenom časopisu Obnovljeni život, u kojem sam analizirao povijesni razvoj medijskih tehnologija kroz prizmu filozofije Richarda Weavera, točnije njegova kapitalnog djela “Ideje imaju posljedice”.

Weaver je jedan od najvažnijih konzervativnih filozofa 20. stoljeća te jedan od mojih glavnih intelektualnih uzora, čije ideje, koncepte i pojmovlje često koristim u svome radu. Posebno je zanimljiva njegova problematizacija modernih medija, o kojoj ćemo govoriti sutra.

Osim analize teze da medij kojim se neka poruka šalje ujedno čini dio same poruke - pa tako *medij* glavnostrujaških medija u novije vrijeme poprima neopravdanu i izvitoperenu ulogu autoriteta - osvrnut ćemo se i na najaktualnije manifestacije ove problematike, poput tzv. fact-checkera. Njih sagledavam kao pokušaj krpanja pukotine na jednosmjernom autoritetu koji Veliki stereoptikon, odnosno sprega glavnostrujaške politike, medija i korporacija, osjeća u svojoj dominaciji nad javnim prostorom.

Drago mi je što ću o svemu tome moći govoriti, kao i što ću moći odati počast velikom Richardu Weaveru, čovjeku čija sintagma stoji u opisu platforme Sapere Aude gotovo od njezinih početaka.

**[#SapereAude](https://www.facebook.com/hashtag/sapereaude?__eep__=6&__cft__[0]=AZbFUUKuirYOxJqyGzK2qHyFlglS0mFf-16DF8tEX6x6EBJy-qc8jdYtl2wlrrKkOiQdeNuT4-qhQ7bWVObbLDt7Mbui_GQ_7E7mhqnztENFKyXM4AaBJB_YAyzAMm1IX_A9PXF6UO8zw8bpQGGF6CMr4D31hJv-sFzb_a0qBzOWgaf7weyhzhcZJSnw92IiGfI3I8Uzl5XyeYuS5YpvKO8R&__tn__=*NK-R-R)**', '<p><img src="https://substackcdn.com/image/fetch/$s_!e22i!,f_auto,q_auto:good,fl_progressive:steep/https%3A%2F%2Fsubstack-post-media.s3.amazonaws.com%2Fpublic%2Fimages%2F50fc8481-d606-4eaa-a7f5-a7796dc09303_639x941.jpeg" alt="Richard Weaver on toughness and heroism — Jordan M. Poss"></p>
