INSERT INTO media (id, publication_id, kind, storage_key, filename, mime_type, byte_size) VALUES ('fc5826ca31504ba9960f8b18b3110a34', '4cd630440b929be61d9c36769b788da2', 'image', 'pub/4cd630440b929be61d9c36769b788da2/fc5826ca31504ba9960f8b18b3110a34/od-drustvenih-mreza-zele-nas-stititi.jpg', 'od-drustvenih-mreza-zele-nas-stititi.jpg', 'image/jpeg', 158945);
INSERT INTO posts (id, publication_id, slug, title, subtitle, body_md, body_html, cover_media_id, category_id, kind, status, published_at) VALUES ('8d6eec4a6eac7e1a5ec7b1fe6115f78e', '4cd630440b929be61d9c36769b788da2', 'od-drustvenih-mreza-zele-nas-stititi-ljudi-koji-ne-znaju-sto-je-zena', 'DEMO ### 438 Od društvenih mreža žele nas štititi ljudi koji ne znaju što je žena', '', '![](https://substackcdn.com/image/fetch/$s_!vLdE!,f_auto,q_auto:good,fl_progressive:steep/https%3A%2F%2Fsubstack-post-media.s3.amazonaws.com%2Fpublic%2Fimages%2F4209e102-3b72-4425-bb45-32e9cdeff10d_1640x924.jpeg)

U jučerašnjem [video osvrtu](https://sapereaudecro.substack.com/p/zasto-se-stranka-mozemo-zalaze-za) pozvao sam na kategoričko odbacivanje Možemovog prijedloga o državnom nadzoru nad društvenim mrežama, rekavši da nas lažno sjajni celofan u koji se taj nadzor umata, a koji oni zovu zaštitom djece od ekrana, ne smije odagnati od razboritog razmišljanja i shvaćanja o kakvim političarima ovdje govorimo.

Gotovo isti dan njihovi kulturni suborci u Europskom parlamentu, uz njihove vlastite europarlamentarne predstavnike, izglasali su da ženom, u očima izokrenutog eurokratskog zakonodavstva, može postati svatko tko se tako samoodredi.

Možemovci koji su svesrdno podržali ovu odluku, uz uobičajenu izdajničko-pasivnu potporu prevladavajućih mlakih deklarativnih konzervativaca, time su dali najbolju moguću antireklamu za svoj spomenuti prijedlog o tobožnjoj zaštiti djece, barem onima među nama koji i dalje imaju oči da vide što se događa oko nas.

Tko podrži Možemov prijedlog sada zna da podržava nadzor nad našim govorom od strane ljudi koji žele kriminalizirati nazivanje žene ženom, a muškarca muškarcem. Uz svu svoju adiktivnost i općenitu toksičnost, društvene mreže u ovome su trenutku posljednji prostor za opovrgavanje dnevnih potpuno poludjelih idejnih izopačina koje ovo doba iznjedruje.

“Provjera dobi” prilikom ulogiravanja nije provjera dobi, već provjera vašeg identiteta kako bi vas se kasnije moglo lakše pravno goniti ako napišete nešto što izlazi iz pravovjerja ovog dekadentnog, urušenog doba.

**#SapereAude**', '<p><img src="https://substackcdn.com/image/fetch/$s_!vLdE!,f_auto,q_auto:good,fl_progressive:steep/https%3A%2F%2Fsubstack-post-media.s3.amazonaws.com%2Fpublic%2Fimages%2F4209e102-3b72-4425-bb45-32e9cdeff10d_1640x924.jpeg" alt=""></p>
<p>U jučerašnjem <a href="https://sapereaudecro.substack.com/p/zasto-se-stranka-mozemo-zalaze-za">video osvrtu</a> pozvao sam na kategoričko odbacivanje Možemovog prijedloga o državnom nadzoru nad društvenim mrežama, rekavši da nas lažno sjajni celofan u koji se taj nadzor umata, a koji oni zovu zaštitom djece od ekrana, ne smije odagnati od razboritog razmišljanja i shvaćanja o kakvim političarima ovdje govorimo.</p>
<p>Gotovo isti dan njihovi kulturni suborci u Europskom parlamentu, uz njihove vlastite europarlamentarne predstavnike, izglasali su da ženom, u očima izokrenutog eurokratskog zakonodavstva, može postati svatko tko se tako samoodredi.</p>
<p>Možemovci koji su svesrdno podržali ovu odluku, uz uobičajenu izdajničko-pasivnu potporu prevladavajućih mlakih deklarativnih konzervativaca, time su dali najbolju moguću antireklamu za svoj spomenuti prijedlog o tobožnjoj zaštiti djece, barem onima među nama koji i dalje imaju oči da vide što se događa oko nas.</p>
<p>Tko podrži Možemov prijedlog sada zna da podržava nadzor nad našim govorom od strane ljudi koji žele kriminalizirati nazivanje žene ženom, a muškarca muškarcem. Uz svu svoju adiktivnost i općenitu toksičnost, društvene mreže u ovome su trenutku posljednji prostor za opovrgavanje dnevnih potpuno poludjelih idejnih izopačina koje ovo doba iznjedruje.</p>
<p>“Provjera dobi” prilikom ulogiravanja nije provjera dobi, već provjera vašeg identiteta kako bi vas se kasnije moglo lakše pravno goniti ako napišete nešto što izlazi iz pravovjerja ovog dekadentnog, urušenog doba.</p>
<p><strong>#SapereAude</strong></p>
