INSERT INTO media (id, publication_id, kind, storage_key, filename, mime_type, byte_size) VALUES ('461469a75f2612ebbcc150d0283f65ea', '4cd630440b929be61d9c36769b788da2', 'image', 'pub/4cd630440b929be61d9c36769b788da2/461469a75f2612ebbcc150d0283f65ea/gostovanje-u-fenomenu-tjedna.jpg', 'gostovanje-u-fenomenu-tjedna.jpg', 'image/jpeg', 65421);
INSERT INTO posts (id, publication_id, slug, title, subtitle, body_md, body_html, cover_media_id, category_id, kind, status, published_at) VALUES ('cec33645efa3a861d068d0fee6192593', '4cd630440b929be61d9c36769b788da2', 'gostovanje-u-fenomenu-tjedna', 'DEMO ### 443 Gostovanje u Fenomenu tjedna', '', '![](https://substackcdn.com/image/fetch/$s_!j9X7!,f_auto,q_auto:good,fl_progressive:steep/https%3A%2F%2Fsubstack-post-media.s3.amazonaws.com%2Fpublic%2Fimages%2F088f1490-8717-4cd7-af7b-9a75ac21a9fa_1080x608.jpeg)

U sinoćnjoj emisiji Fenomen tjedna Marina Vlahovića gostovao sam zajedno s profesorom Tomislavom Sunićem.

Proanalizirali smo aktualni rat Izraela i Irana, problematizirajući pritom, kako sam ga nazvao, nezdrav odnos SAD-a i Izraela. Kritički smo pristupili i Trumpovoj administraciji, koja je u ovome trenutku izdala gotovo sve ključne stavke koje su nekada sačinjavale pokret tzv. trumpizma. Pokret čija sam načela godinama branio.

Osobno sam težio ta geopolitička previranja kontekstualizirati u etički okvir koji današnjem svijetu toliko nedostaje. Nadalje, sve smo to sagledali i iz perspektive Hrvatske, kao zemlje ukorijenjene u katolički nauk, koja ne može pristati ni na koju podivljalu stranu na Bliskom istoku, uključujući ni onu američku. Unatoč svim Trumpovim deklarativnim antiestablišmentskim obećanjima, on nažalost nastavlja hraniti prekooceansku proratnu mašinu.

U drugom dijelu emisije još sam jednom apostrofirao da EU u cijeloj ovoj divljoj svjetskoratnoj priči djeluje kao troma, jalova, nebitna struktura koja svoju jalovost nastoji prikriti birokratskim, regulatornim i tehnokratskim nasiljem nad vlastitim stanovništvom.

Zahvaljujem gospodinu Vlahoviću na pozivu. Čast mi je što sam mogao nastupiti s prof. Sunićem, jednim od najvećih živućih hrvatskih intelektualaca. Poveznicu na emisiju prilažem u komentarima.

#SapereAude', '<p><img src="https://substackcdn.com/image/fetch/$s_!j9X7!,f_auto,q_auto:good,fl_progressive:steep/https%3A%2F%2Fsubstack-post-media.s3.amazonaws.com%2Fpublic%2Fimages%2F088f1490-8717-4cd7-af7b-9a75ac21a9fa_1080x608.jpeg" alt=""></p>
<p>U sinoćnjoj emisiji Fenomen tjedna Marina Vlahovića gostovao sam zajedno s profesorom Tomislavom Sunićem.</p>
<p>Proanalizirali smo aktualni rat Izraela i Irana, problematizirajući pritom, kako sam ga nazvao, nezdrav odnos SAD-a i Izraela. Kritički smo pristupili i Trumpovoj administraciji, koja je u ovome trenutku izdala gotovo sve ključne stavke koje su nekada sačinjavale pokret tzv. trumpizma. Pokret čija sam načela godinama branio.</p>
<p>Osobno sam težio ta geopolitička previranja kontekstualizirati u etički okvir koji današnjem svijetu toliko nedostaje. Nadalje, sve smo to sagledali i iz perspektive Hrvatske, kao zemlje ukorijenjene u katolički nauk, koja ne može pristati ni na koju podivljalu stranu na Bliskom istoku, uključujući ni onu američku. Unatoč svim Trumpovim deklarativnim antiestablišmentskim obećanjima, on nažalost nastavlja hraniti prekooceansku proratnu mašinu.</p>
<p>U drugom dijelu emisije još sam jednom apostrofirao da EU u cijeloj ovoj divljoj svjetskoratnoj priči djeluje kao troma, jalova, nebitna struktura koja svoju jalovost nastoji prikriti birokratskim, regulatornim i tehnokratskim nasiljem nad vlastitim stanovništvom.</p>
<p>Zahvaljujem gospodinu Vlahoviću na pozivu. Čast mi je što sam mogao nastupiti s prof. Sunićem, jednim od najvećih živućih hrvatskih intelektualaca. Poveznicu na emisiju prilažem u komentarima.</p>
