INSERT INTO media (id, publication_id, kind, storage_key, filename, mime_type, byte_size) VALUES ('6f0aac5fcd78c264c7b778337a707b4e', '4cd630440b929be61d9c36769b788da2', 'image', 'pub/4cd630440b929be61d9c36769b788da2/6f0aac5fcd78c264c7b778337a707b4e/najava-tribine.png', 'najava-tribine.png', 'image/png', 153757);
INSERT INTO posts (id, publication_id, slug, title, subtitle, body_md, body_html, cover_media_id, category_id, kind, status, published_at) VALUES ('6d5d7f229a9cb9a0196f6d54db2c5e50', '4cd630440b929be61d9c36769b788da2', 'najava-tribine', 'DEMO ### 465 Najava tribine', '"Homo Americanus: Druga strana američkog konzervativizma"', '![](https://substackcdn.com/image/fetch/$s_!ZtPW!,f_auto,q_auto:good,fl_progressive:steep/https%3A%2F%2Fsubstack-post-media.s3.amazonaws.com%2Fpublic%2Fimages%2F106e4427-8ef2-49eb-8d3f-f6b3f7d66951_1414x2000.png)

Američka politička desnica desetljećima je okupirana takozvanim neokonzervativnim pokretom, čije slabosti postaju sve jasnije sve većem broju ljudi. Intervencionistička i proratna politika, nekritičko suobličavanje s liberalizmom, kao i nezdrave pseudoteološke poveznice toga pokreta s pojedinim državnim “strateškim partnerima” gotovo su potpuno izjednačile prekooceansku glavnostrujašku desnicu s njezinim deklariranim protivnikom s lijevoliberalnog spektra.

Destruktivni novi bliskoistočni rat, kao vrhunac neispunjenih obećanja aktualnog američkog vodstva, kap je koja je prelila čašu i koja poziva sve konzervativce - a napose one ukorijenjene u katoličkom nauku, koji jasno raspoznaje kriterije pravednog i nepravednog ratovanja - da pruže otpor neokonzervativizmu i dignu glas za jedan zdraviji konzervativizam. Američki bi eksperiment mogao ovisiti upravo o tom glasu.

O svemu tome govorit ćemo s biranim gostima u četvrtak, 28.5., u 19 sati. Ulaz je slobodan.

#SapereAude', '<p><img src="https://substackcdn.com/image/fetch/$s_!ZtPW!,f_auto,q_auto:good,fl_progressive:steep/https%3A%2F%2Fsubstack-post-media.s3.amazonaws.com%2Fpublic%2Fimages%2F106e4427-8ef2-49eb-8d3f-f6b3f7d66951_1414x2000.png" alt=""></p>
<p>Američka politička desnica desetljećima je okupirana takozvanim neokonzervativnim pokretom, čije slabosti postaju sve jasnije sve većem broju ljudi. Intervencionistička i proratna politika, nekritičko suobličavanje s liberalizmom, kao i nezdrave pseudoteološke poveznice toga pokreta s pojedinim državnim “strateškim partnerima” gotovo su potpuno izjednačile prekooceansku glavnostrujašku desnicu s njezinim deklariranim protivnikom s lijevoliberalnog spektra.</p>
<p>Destruktivni novi bliskoistočni rat, kao vrhunac neispunjenih obećanja aktualnog američkog vodstva, kap je koja je prelila čašu i koja poziva sve konzervativce - a napose one ukorijenjene u katoličkom nauku, koji jasno raspoznaje kriterije pravednog i nepravednog ratovanja - da pruže otpor neokonzervativizmu i dignu glas za jedan zdraviji konzervativizam. Američki bi eksperiment mogao ovisiti upravo o tom glasu.</p>
<p>O svemu tome govorit ćemo s biranim gostima u četvrtak, 28.5., u 19 sati. Ulaz je slobodan.</p>
<p>#SapereAude</p>
