INSERT INTO media (id, publication_id, kind, storage_key, filename, mime_type, byte_size) VALUES ('6e1bcc56aca5e513a431dc152dfc0239', '4cd630440b929be61d9c36769b788da2', 'image', 'pub/4cd630440b929be61d9c36769b788da2/6e1bcc56aca5e513a431dc152dfc0239/doite-na-mostovu-tribinu-o-zastiti.jpg', 'doite-na-mostovu-tribinu-o-zastiti.jpg', 'image/jpeg', 199744);
INSERT INTO posts (id, publication_id, slug, title, subtitle, body_md, body_html, cover_media_id, category_id, kind, status, published_at) VALUES ('780e7c89a48eadcc9c166cbf6121c97d', '4cd630440b929be61d9c36769b788da2', 'dodite-na-mostovu-tribinu-o-zastiti-gotovine', 'DEMO ### 476 Dođite na Mostovu tribinu o zaštiti gotovine', '11. lipnja | 19 sati | Radnička 52, Zagreb', '![](https://substackcdn.com/image/fetch/$s_!a28q!,f_auto,q_auto:good,fl_progressive:steep/https%3A%2F%2Fsubstack-post-media.s3.amazonaws.com%2Fpublic%2Fimages%2F7c262dc2-0091-456d-80ab-7a1548c06f3d_1080x1350.jpeg)

Večeras nastavljamo sa serijom tribina MOST-a na temu ustavne zaštite gotovine, ovoga puta u Zagrebu.

Agresivno gurane tehnologije digitalnog eura i digitalnog identiteta zajedno tvore distopijsku arhitekturu globalističkog tehnokratskog nadzora, pri čemu digitalizacija novca, lišena postojanja fizičke valute, redefinira sam pojam novca. On tako prestaje biti simbol slobodne razmjene privatnog vlasništva i postaje svojevrsna nakupina tokena koje vlast može dodjeljivati ili oduzimati sukladno poslušnosti građana njezinim zamislima. Time se i čovjek redefinira iz slobodnomislećeg bića i stvaratelja legitimiteta u pasivnu upravljivu brojku.

Jednostavnije rečeno, bez mogućnosti držanja svoga novca u vlastitim rukama, on u ovo tehnomanijakalno vrijeme nije i ne može biti siguran.

Vidimo se stoga na tribini večeras u 19 sati u Radničkoj 52. Uz mene na njoj će nastupiti prof. Ivor Altaras Penda, prof. Branimir Pervan i saborski zastupnik Zvonimir Troskot.

Radi se o jednoj od najvažnijih ali i najzapostavljenijih tema današnjice, tema koje će zasigurno u nekom trenutku dotaknuti živote svakog od nas.

#SapereAude', '<p><img src="https://substackcdn.com/image/fetch/$s_!a28q!,f_auto,q_auto:good,fl_progressive:steep/https%3A%2F%2Fsubstack-post-media.s3.amazonaws.com%2Fpublic%2Fimages%2F7c262dc2-0091-456d-80ab-7a1548c06f3d_1080x1350.jpeg" alt=""></p>
